(6, 'building-cleaning', 26, '汚れ', 'よごれ', 'yogore', 'kotoran', 'Kata benda', 'Segala macam kotoran yang menempel di permukaan.', '物についたきたないもの', 'kotoran yang menempel pada permukaan benda', '汚れの種類を確認してから掃除します。', 'よごれのしゅるいをかくにんしてからそうじします。', 'Kami memeriksa jenis kotoran sebelum membersihkan.'),
(6, 'building-cleaning', 27, 'ほこり', 'ほこり', 'hokori', 'debu', 'Kata benda', 'Partikel kecil yang menumpuk di permukaan.', '細かいちり', 'partikel halus yang menumpuk di permukaan dan sudut ruangan', '棚の上のほこりを払います。', 'たなのうえのほこりをはらいます。', 'Debu di atas rak dibersihkan.'),
(6, 'building-cleaning', 28, '水あか', 'みずあか', 'mizuaka', 'kerak air', 'Kata benda', 'Kerak putih dari air yang mengering di wastafel atau kaca.', '水が乾いてできる白い汚れ', 'kerak putih dari mineral air yang mengering di wastafel, keran, atau kaca', '蛇口の水あかを落とします。', 'じゃぐちのみずあかをおとします。', 'Kerak air di keran dibersihkan.'),
(6, 'building-cleaning', 29, '尿石', 'にょうせき', 'nyōseki', 'kerak urine', 'Kata benda', 'Kerak keras dari urine di toilet dan urinoir.', '便器につく尿のかたまり', 'kerak keras dari endapan urine di toilet yang menyebabkan bau', '尿石は酸性洗剤で落とします。', 'にょうせきはさんせいせんざいでおとします。', 'Kerak urine dibersihkan dengan deterjen asam.'),
(6, 'building-cleaning', 30, 'カビ', 'カビ', 'kabi', 'jamur', 'Kata benda', 'Jamur yang tumbuh di tempat lembap.', '湿ったところに生える菌', 'jamur yang tumbuh di tempat lembap seperti kamar mandi', '浴室のカビを防ぐために換気します。', 'よくしつのカビをふせぐためにかんきします。', 'Kami membuka ventilasi untuk mencegah jamur di kamar mandi.'),
(6, 'building-cleaning', 31, '手あか', 'てあか', 'teaka', 'bekas tangan', 'Kata benda', 'Kotoran berminyak dari tangan di pintu atau tombol.', '手でさわってついた汚れ', 'bekas kotoran berminyak dari tangan di gagang pintu atau tombol', 'ドアノブの手あかを拭き取ります。', 'ドアノブのてあかをふきとります。', 'Bekas tangan di gagang pintu dilap.'),
(6, 'building-cleaning', 32, '拭き取り', 'ふきとり', 'fukitori', 'mengelap sampai bersih', 'Kata benda', 'Mengelap kotoran sampai hilang.', '汚れをふいて取ること', 'mengelap permukaan sampai kotoran terangkat', '洗剤が残らないように拭き取りをします。', 'せんざいがのこらないようにふきとりをします。', 'Kami mengelap agar deterjen tidak tertinggal.'),
(6, 'building-cleaning', 33, '水拭き', 'みずぶき', 'mizubuki', 'mengelap basah', 'Kata benda', 'Mengelap dengan kain basah.', 'ぬれた布でふくこと', 'mengelap permukaan dengan kain yang dibasahi air', '床を水拭きしてから乾拭きします。', 'ゆかをみずぶきしてからからぶきします。', 'Lantai dilap basah, lalu dilap kering.'),
(6, 'building-cleaning', 34, '乾拭き', 'からぶき', 'karabuki', 'mengelap kering', 'Kata benda', 'Mengelap dengan kain kering untuk menghilangkan bekas air.', '乾いた布でふくこと', 'mengelap dengan kain kering agar tidak meninggalkan bekas air', '鏡は最後に乾拭きします。', 'かがみはさいごにからぶきします。', 'Cermin dilap kering di tahap akhir.'),
(6, 'building-cleaning', 35, '除菌', 'じょきん', 'jokin', 'menghilangkan kuman', 'Kata benda', 'Mengurangi kuman di permukaan yang sering disentuh.', '菌を取り除くこと', 'mengurangi jumlah kuman pada permukaan yang sering disentuh', '手すりは毎日除菌します。', 'てすりはまいにちじょきんします。', 'Pegangan tangga dibersihkan dari kuman setiap hari.'),
(6, 'building-cleaning', 36, '消毒', 'しょうどく', 'shōdoku', 'disinfeksi', 'Kata benda', 'Membunuh kuman dengan bahan kimia atau alkohol.', '薬などで菌を殺すこと', 'membunuh kuman menggunakan alkohol atau bahan disinfektan', 'トイレの便座を消毒します。', 'トイレのべんざをしょうどくします。', 'Dudukan toilet didisinfeksi.'),
(6, 'building-cleaning', 37, '感染予防', 'かんせんよぼう', 'kansen yobō', 'pencegahan infeksi', 'Kata benda', 'Upaya mencegah penyebaran penyakit.', '病気がうつるのを防ぐこと', 'tindakan untuk mencegah penyebaran penyakit menular', '感染予防のためにマスクをつけます。', 'かんせんよぼうのためにマスクをつけます。', 'Saya memakai masker untuk mencegah infeksi.'),
(6, 'building-cleaning', 38, '手袋', 'てぶくろ', 'tebukuro', 'sarung tangan', 'Kata benda', 'Alat pelindung tangan saat memakai bahan kimia.', '手を守るためにはめるもの', 'pelindung tangan dari bahan kimia dan kotoran', '薬剤を使うときは必ず手袋をします。', 'やくざいをつかうときはかならずてぶくろをします。', 'Saat memakai bahan kimia, wajib memakai sarung tangan.'),
(6, 'building-cleaning', 39, '保護具', 'ほごぐ', 'hogogu', 'alat pelindung diri', 'Kata benda', 'Perlengkapan pelindung seperti sarung tangan, masker, dan kacamata.', '体を守るための道具', 'perlengkapan untuk melindungi tubuh dari bahaya saat bekerja', '作業の前に保護具を確認します。', 'さぎょうのまえにほごぐをかくにんします。', 'Sebelum bekerja, alat pelindung diri diperiksa.'),
(6, 'building-cleaning', 40, 'ゴーグル', 'ゴーグル', 'gōguru', 'kacamata pelindung', 'Kata benda', 'Pelindung mata dari cipratan bahan kimia.', '目を守るめがね', 'kacamata pelindung agar mata tidak terkena cipratan cairan', '剥離作業ではゴーグルをかけます。', 'はくりさぎょうではゴーグルをかけます。', 'Saat mengelupas wax, kami memakai kacamata pelindung.'),
(6, 'building-cleaning', 41, '作業着', 'さぎょうぎ', 'sagyōgi', 'baju kerja', 'Kata benda', 'Pakaian khusus untuk bekerja.', '仕事のときに着る服', 'pakaian khusus yang dipakai saat bekerja', '作業着に着替えてから現場に行きます。', 'さぎょうぎにきがえてからげんばにいきます。', 'Saya berganti baju kerja sebelum ke lokasi.'),
(6, 'building-cleaning', 42, '安全靴', 'あんぜんぐつ', 'anzengutsu', 'sepatu keselamatan', 'Kata benda', 'Sepatu yang melindungi kaki dan tidak licin.', '足を守るじょうぶな靴', 'sepatu kuat yang melindungi kaki dan mencegah tergelincir', '床洗浄のときは滑りにくい安全靴をはきます。', 'ゆかせんじょうのときはすべりにくいあんぜんぐつをはきます。', 'Saat mencuci lantai, saya memakai sepatu keselamatan anti-licin.'),
(6, 'building-cleaning', 43, '脚立', 'きゃたつ', 'kyatatsu', 'tangga lipat', 'Kata benda', 'Tangga lipat untuk bekerja di tempat tinggi.', '高いところで使う折りたたみのはしご', 'tangga lipat berkaki empat untuk bekerja di tempat tinggi', '脚立に乗るときは二人で作業します。', 'きゃたつにのるときはふたりでさぎょうします。', 'Saat naik tangga lipat, bekerja berdua.'),
(6, 'building-cleaning', 44, '転倒', 'てんとう', 'tentō', 'jatuh / terpeleset', 'Kata benda', 'Kecelakaan jatuh karena lantai basah atau licin.', 'ころんで倒れること', 'jatuh atau terpeleset, sering terjadi karena lantai basah', '転倒しないようにゆっくり歩きます。', 'てんとうしないようにゆっくりあるきます。', 'Saya berjalan pelan agar tidak terjatuh.'),
